var (
	addr         = flag.String("address", ":7317", "the address to listen to")
	quiet        = flag.Bool("quiet", false, "silence the log")
	allowAllPath = flag.Bool("allow-all", false, "allow all path set by the client")
)

func main() {
	flag.Parse()

	m := launcher.NewManager()

	if !*quiet {
		m.Logger = log.New(os.Stdout, "", 0)
	}

	if *allowAllPath {
		m.BeforeLaunch = func(_ *launcher.Launcher, _ http.ResponseWriter, _ *http.Request) {}
	}

	l, err := net.Listen("tcp", *addr)
	if err != nil {
		utils.E(err)
	}

	if !*quiet {
		fmt.Println("[rod-manager] listening on:", l.Addr().String())
	}

	srv := &http.Server{Handler: m}
	utils.E(srv.Serve(l))
}","lineStart":1,"lineEnd":46,"totalLines":46,"truncated":false}},"title":"repos/ruangong-0707/rod/lib/launcher/rod-manager/main.go","time":{"start":1783568755501,"end":1783568755517}},"id":"prt_f44fb6629001CeazBMtmNaG0ZH","sessionID":"ses_0bb1b98b9ffeWc0xu5pttFGG8a","messageID":"msg_f44f83ec70014TO26fRMLKaknN"}}

